Translate("frFR", "arathi-highlands", {
	title = "Hautes-terres d'Arathi",
	aliases = { "Arathi" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Hautes-terres d'Arathi sont un pays haut et sec d'herbe, de vent et de pierre grise, qui s'étend entre les {link:hillsbrad-foothills}Contreforts d'Hillsbrad{/link} et {link:the-hinterlands}les Hinterlands{/link}. C'est ici que l'humanité devint d'abord une nation. La forteresse de {link:stromgarde-keep}Strom{/link} s'éleva sur ces plaines quand les tribus des hommes étaient encore en guerre contre les trolls, et tous les royaumes humains du monde en descendent. Aujourd'hui, les hautes-terres n'appartiennent à personne. Stromgarde, le royaume qui garda le nom de Strom, est tombé en ruine. Les orcs tiennent {link:hammerfall}Trépas-d'Orgrim{/link} sur les collines de l'est, sur le sol même où l'{link:alliance}Alliance{/link} les gardait autrefois enchaînés. Les derniers soldats de Stromgarde attendent au {link:refuge-pointe}Refuge de l'Ornière{/link} le jour où ils pourront rentrer chez eux.]=],
		},
		{
			title = "Origines",
			text = [=[Quelque vingt-huit siècles avant la {link:dark-portal}Porte des Ténèbres{/link}, les tribus humaines du nord étaient dispersées et en guerre les unes contre les autres, et les {link:trolls}trolls{/link} Amani faisaient d'elles toutes leurs proies. {link:thoradin}Thoradin{/link}, seigneur de guerre de la tribu Arathi, unit les tribus et éleva la forteresse de {link:stromgarde-keep}Strom{/link} dans ces hautes-terres. La terre ouverte et aride privait les trolls des embuscades en forêt qu'ils affectionnaient. À Strom, les elfes de {link:quel-thalas}Quel'Thalas{/link} enseignèrent les voies de la {link:arcane-magic}magie{/link} à cent humains, et ensemble les deux peuples brisèrent les Amani lors des {link:troll-wars}guerres des Trolls{/link}. Au fil des siècles, l'empire d'{link:arathor}Arathor{/link} s'étendit sur le continent et laissa derrière lui sa première cité. Les grandes familles partirent vers le nord, et le dernier de la lignée de Thoradin fit voile vers le sud pour fonder le royaume qui devint {link:stormwind-city}Stormwind{/link}. Les Trollbane, héritiers d'un général des guerres des Trolls, restèrent. Ils donnèrent à la vieille cité le nom de Stromgarde.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Le roi {link:thoras-trollbane}Thoras Trollbane{/link} est mort, et sa cité est en ruine. Les {link:boulderfist-ogres}ogres Rochepoing{/link} et les brigands du {link:syndicate}Syndicat{/link} tiennent la plus grande partie de {link:stromgarde-keep}Stromgarde{/link}, et le reste de son armée s'accroche à un seul quartier sous les ordres du prince {link:prince-galen-trollbane}Galen Trollbane{/link}. Au {link:refuge-pointe}Refuge de l'Ornière{/link}, le capitaine {link:captain-nials}Nials{/link} rassemble les forces qui restent, et la {link:league-of-arathor}Ligue d'Arathor{/link} se prépare à reprendre la terre par les armes. À l'est, {link:hammerfall}Trépas-d'Orgrim{/link} est devenu un avant-poste de la {link:horde}Horde{/link}. Ses orcs repoussent les {link:witherbark-trolls}trolls Witherbark{/link} et les ogres Rochepoing, qui se sont alliés contre eux. Des chasseurs {link:darkspear-trolls}Darkspear{/link} envoyés par {link:vol-jin}Vol'jin{/link} cherchent une épée ancienne dans le tombeau des Trollbane, et les {link:defilers}Profanateurs réprouvés{/link} disputent la riche vallée du {link:arathi-basin}Bassin d'Arathi{/link}. Sous la terre, une voix appelle à travers des éclats de cristal et supplie qu'on la libère.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les soldats de {link:stromgarde-keep}Stromgarde{/link}.{/b} Les derniers de l'armée du royaume, partagés entre les ruines de leur capitale et le camp du {link:refuge-pointe}Refuge de l'Ornière{/link}.
• {b}La {link:horde}Horde{/link} de {link:hammerfall}Trépas-d'Orgrim{/link}.{/b} {link:orcs}Orcs{/link}, {link:darkspear-trolls}trolls Darkspear{/link} et {link:forsaken}Réprouvés{/link}, en guerre contre toutes les autres puissances des hautes-terres.
• {b}Le {link:syndicate}Syndicat{/link}.{/b} Voleurs et démonistes au service des seigneurs déchus d'{link:alterac-mountains}Alterac{/link}.
• {b}Les {link:boulderfist-ogres}ogres Rochepoing{/link}.{/b} La plus grande armée des hautes-terres, de {link:boulder-gor}Boulder'gor{/link} au {link:boulderfist-hall}Hall Rochepoing{/link}.
• {b}Les {link:witherbark-trolls}trolls Witherbark{/link}.{/b} {link:trolls}Trolls{/link} des forêts du sud-est, les plus anciens ennemis de Strom.
• {b}Les {link:drywhisker-kobolds}kobolds Sèches-moustaches{/link}.{/b} Creuseurs de la gorge de l'est, et alliés des géants.
• {b}Les Pillards des Flots noirs.{/b} Pirates de {link:booty-bay}Baie-du-Butin{/link} échoués dans la Crique de Faldir.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}{link:arathor}Arathor{/link}.{/b} {link:thoradin}Thoradin{/link} unit les tribus et éleva {link:stromgarde-keep}Strom{/link}. D'ici, l'humanité partit fonder ses royaumes.
• {b}Les sept royaumes.{/b} Quand Strom déclina, ses nobles et sa lignée royale s'en allèrent. Les Trollbane restèrent et régnèrent sur Stromgarde.
• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} {link:thoras-trollbane}Thoras Trollbane{/link} fit entrer Stromgarde dans l'{link:alliance}Alliance{/link} de {link:lordaeron}Lordaeron{/link}.
• {b}Les camps.{/b} Après la guerre, l'Alliance garda des orcs vaincus dans un camp des collines de l'est. {link:thrall}Thrall{/link} et {link:orgrim-doomhammer}Orgrim Doomhammer{/link} le brisèrent, et Doomhammer y tomba.
• {b}La chute.{/b} Après la chute de Lordaeron, Stromgarde tomba aux mains des ogres et des brigands, et son peuple se dispersa.]=],
		},
		{
			title = "Légendes des hautes-terres",
			text = [=[• Quatre cercles de pierres levées se dressent à travers les hautes-terres. Des esprits de la terre, du feu, de l'eau et de l'air marchent parmi elles.
• Les soldats du {link:refuge-pointe}Refuge de l'Ornière{/link} ont juré de ne pas quitter les hautes-terres avant que la bannière du roi ne flotte de nouveau sur {link:stromgarde-keep}Stromgarde{/link}.
• Les orcs de {link:hammerfall}Trépas-d'Orgrim{/link} disent que la tache noire dans la terre de leur camp est le sang d'{link:orgrim-doomhammer}Orgrim Doomhammer{/link}.]=],
		},
	},
})

Translate("frFR", "stromgarde-keep", {
	title = "Donjon de Stromgarde",
	aliases = { "Stromgarde", "Strom" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Donjon de Stromgarde est tout ce qui reste de Strom, la première cité de l'humanité, au sud-ouest des hautes-terres. Ses murs abritent aujourd'hui trois armées à la fois. Les {link:boulderfist-ogres}ogres Rochepoing{/link} et leurs alliés {link:witherbark-trolls}Witherbark{/link} tiennent une grande partie de la cité et occupent la Tour d'{link:arathor}Arathor{/link}, où l'archimage Trelane livra un dernier combat avant de fuir. Le {link:syndicate}Syndicat{/link} tient un autre quartier sous les ordres de {link:lord-falconcrest}Lord Falconcrest{/link}. Les derniers soldats de Stromgarde gardent le quartier de la chapelle sous les ordres du prince {link:prince-galen-trollbane}Galen Trollbane{/link}. Derrière la chapelle se trouve le Sanctuaire, où le roi {link:thoras-trollbane}Thoras{/link} repose dans un tombeau scellé avec l'épée {link:trol-kalar}Trol'kalar{/link}.]=],
		},
		{
			title = "L'impasse",
			text = [=[Aucune des trois ne parvient à chasser les autres. Chacune combat ses deux rivales, et la cité saigne un peu plus chaque jour.]=],
		},
	},
})

Translate("frFR", "refuge-pointe", {
	title = "Refuge de l'Ornière",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Refuge de l'Ornière est un camp fortifié sur une colline au cœur des hautes-terres. Il abrite ce qui reste de l'armée de {link:stromgarde-keep}Stromgarde{/link} après la chute de sa capitale. Le capitaine {link:captain-nials}Nials{/link} y commande, et ses soldats ont juré de ne pas quitter les hautes-terres avant que leur cité ne soit de nouveau à eux. Les vivres montent par les routes depuis {link:southshore}Southshore{/link} quand le {link:syndicate}Syndicat{/link} les laisse passer. Depuis peu, le camp s'est rempli de nouvelles bannières : la {link:league-of-arathor}Ligue d'Arathor{/link} s'y rassemble pour la lutte autour du {link:arathi-basin}Bassin d'Arathi{/link}. Deux envoyés d'un archimage de {link:stormwind-city}Stormwind{/link} ont aussi leurs tentes au Refuge.]=],
		},
	},
})

Translate("frFR", "hammerfall", {
	title = "Trépas-d'Orgrim",
	sections = {
		{
			title = "Résumé",
			text = [=[Trépas-d'Orgrim se dresse sur les collines de l'est des hautes-terres. Après la {link:second-war}Deuxième Guerre{/link}, ce fut l'un des {link:internment-camps}camps d'internement{/link} où l'{link:alliance}Alliance{/link} gardait les orcs vaincus. Ses cages, ses piloris et ses gibets sont encore debout. {link:thrall}Thrall{/link} et {link:orgrim-doomhammer}Orgrim Doomhammer{/link} vinrent libérer ses prisonniers, et c'est ici que Doomhammer fut frappé dans le dos par la lance d'un chevalier. Des années plus tard, les orcs revinrent et firent de la ruine leur demeure. Aujourd'hui, {link:drum-fel}Drum Fel{/link} tient Trépas-d'Orgrim pour la {link:horde}Horde{/link}, avec parmi les siens des trolls {link:darkspear-trolls}Darkspear{/link}, des {link:defilers}Profanateurs réprouvés{/link} et un médecin-chef de la Horde. {link:trolls}Trolls{/link} et ogres assaillent ses murs sans relâche.]=],
		},
	},
})

Translate("frFR", "go-shek-farm", {
	title = "Ferme de Go'Shek",
	sections = {
		{
			title = "Résumé",
			text = [=[La Ferme de Go'Shek s'étend dans les basses terres de l'est, au sud-ouest de {link:hammerfall}Trépas-d'Orgrim{/link}. Des péons de Trépas-d'Orgrim travaillent ses champs sous l'œil de grunts orcs, et sa récolte nourrit l'avant-poste. Mais la ferme cache plus que du grain. Dans une petite maison à sa lisière sud, l'apothicaire réprouvé Jorell mène des expériences mortelles, et un coursier porte ses découvertes vers l'ouest, jusqu'à {link:tarren-mill}Moulin-de-Tarren{/link}. Deux compagnons de {link:phin-odelic}Phin Odelic{/link} surveillent la ferme depuis les collines depuis des jours.]=],
		},
	},
})

Translate("frFR", "circle-of-inner-binding", {
	title = "Cercle de lien intérieur",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Cercle de lien intérieur est un anneau de pierres levées sur la plaine au nord-est de {link:stromgarde-keep}Stromgarde{/link}. En son cœur se dresse la Pierre de lien intérieur, la plus puissante des quatre pierres qui retiennent quelque chose captif au plus profond des hautes-terres. À côté repose une clé de voûte chargée de la puissance de la terre. Des esprits de pierre errent dans le cercle comme des exilés, et ils ne tolèrent personne à leur approche. Aucune chronique ne dit qui dressa les pierres, ni quand.]=],
		},
	},
})

Translate("frFR", "circle-of-east-binding", {
	title = "Cercle de lien oriental",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Cercle de lien oriental se dresse sur les hauteurs au nord-ouest de {link:hammerfall}Trépas-d'Orgrim{/link}. C'est l'un des quatre anneaux de pierres levées qui gardent un prisonnier enchaîné sous les hautes-terres. Sa Pierre de lien oriental est veillée par des esprits de l'eau, les exilés déferlants, qui s'élèvent comme des vagues parmi les pierres. La pierre renferme une clé qui lui est propre, et quiconque veut ouvrir la Pierre de lien intérieur doit d'abord la prendre au cercle de l'est.]=],
		},
	},
})

Translate("frFR", "circle-of-west-binding", {
	title = "Cercle de lien occidental",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Cercle de lien occidental se dresse au nord-ouest des hautes-terres, non loin du {link:thoradin-s-wall}Mur de Thoradin{/link}. C'est l'un des quatre anneaux de pierres levées qui gardent un prisonnier enchaîné sous la terre. Des esprits du feu, les exilés ardents, gardent sa Pierre de lien occidental. La clé que renferme cette pierre est l'une des trois nécessaires pour ouvrir la Pierre de lien intérieur. Les camps du {link:syndicate}Syndicat{/link}, tout proches à Nordclos, ont appris à garder leurs distances.]=],
		},
	},
})

Translate("frFR", "circle-of-outer-binding", {
	title = "Cercle de lien extérieur",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Cercle de lien extérieur se dresse au centre des hautes-terres, sur la plaine au sud-est du {link:refuge-pointe}Refuge de l'Ornière{/link}. C'est l'un des quatre anneaux de pierres levées qui retiennent un captif sous la terre. Sa Pierre de lien extérieur est gardée par des {link:vanishing-of-the-wind-spirits}esprits du vent{/link} et de l'orage, les exilés tonnants. La pierre renferme la troisième des clés qui ouvrent la Pierre de lien intérieur. Les voyageurs des routes du Refuge la voient chaque jour et savent peu de chose de ce qu'elle garde.]=],
		},
	},
})

Translate("frFR", "northfold-manor", {
	title = "Manoir de Nordclos",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Manoir de Nordclos est un domaine au nord-ouest des hautes-terres, sur les routes entre les terres de {link:stromgarde-keep}Stromgarde{/link} et {link:hillsbrad-foothills}Hillsbrad{/link}. Le {link:syndicate}Syndicat{/link} en a fait une base. Ses bandits de grand chemin et ses mercenaires fondent sur les convois de vivres qui montent de {link:southshore}Southshore{/link} au {link:refuge-pointe}Refuge de l'Ornière{/link}, et les soldats de Stromgarde en ont faim. Des choses pires s'y font aussi. Le chaman {link:tor-gan}Tor'gan{/link} de {link:hammerfall}Trépas-d'Orgrim{/link} a trouvé sur ses terres des traces d'invocation démoniaque, ainsi qu'une amulette de pierre de sang épuisée par l'œuvre.]=],
		},
	},
})

Translate("frFR", "faldir-s-cove", {
	title = "La Crique de Faldir",
	sections = {
		{
			title = "Résumé",
			text = [=[La Crique de Faldir est un petit port de la côte sud, au pied des falaises à l'ouest de {link:stromgarde-keep}Stromgarde{/link}. Trois navires des {red:blackwater-raiders}Pillards des Flots noirs{/red} de {link:booty-bay}Baie-du-Butin{/link} vinrent ici à la recherche d'un trésor elfique perdu. Seul le {i}Harbinger{/i} du capitaine {link:shakes-o-breen}O'Breen{/link} atteignit le rivage. Tandis que les autres suivaient, la mer gronda, la marée se retira, et le {i}Spirit of Silverpine{/i} et le {i}Maiden's Folly{/i} se brisèrent sur le récif. Les {link:naga}nagas{/link} Daggerspine du Récif englouti tuèrent la plupart des survivants. L'équipage échoué tient à présent un camp sur la plage.]=],
		},
	},
})

Translate("frFR", "witherbark-village", {
	title = "Village Witherbark",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Village Witherbark est la demeure des {link:witherbark-trolls}trolls Witherbark{/link}, au sud-est des hautes-terres. Leurs huttes se dressent parmi les collines, et leurs sorciers-docteurs, leurs chasseurs de têtes et leurs chasseurs des ombres y perpétuent les anciennes coutumes de leur peuple. Derrière le village s'ouvrent les Cavernes Witherbark, où se réunissent les chefs de bande de la tribu. D'ici, les trolls partent piller {link:hammerfall}Trépas-d'Orgrim{/link}, et c'est ici que {link:drum-fel}Drum Fel{/link} envoya les premiers de ses soldats pour rendre les coups.]=],
		},
	},
})

Translate("frFR", "boulderfist-hall", {
	title = "Hall Rochepoing",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Hall Rochepoing est une forteresse des {link:boulderfist-ogres}ogres Rochepoing{/link} au sud des hautes-terres, à l'est du {link:thandol-span}Viaduc de Thandol{/link}. Ses grottes sont tenues par des brutes et des ogres mages, sous les ordres de {link:kor-gresh-coldrage}Kor'gresh Coldrage{/link}, qui maintient les siens dans le rang à coups de glace lancés par une baguette volée. Les ogres qui attaquent {link:hammerfall}Trépas-d'Orgrim{/link} viennent d'ici, et les nains du Viaduc ont appris à surveiller ses collines. On dit aussi que Molok the Crusher rôde sur ses pentes.]=],
		},
	},
})

Translate("frFR", "boulder-gor", {
	title = "Boulder'gor",
	sections = {
		{
			title = "Résumé",
			text = [=[Boulder'gor est un tertre d'ogres sur les collines au nord-est de {link:stromgarde-keep}Stromgarde{/link}. Les {link:boulderfist-ogres}ogres Rochepoing{/link} qui y vivent sont moins nombreux et plus faibles que ceux du {link:boulderfist-hall}Hall Rochepoing{/link}, mais des {link:witherbark-trolls}trolls Witherbark{/link} partagent leur camp, et les deux peuples pillent ensemble. Pour la {link:horde}Horde{/link}, Boulder'gor est devenu une épreuve. Tallow, de {link:tarren-mill}Moulin-de-Tarren{/link}, y envoie d'abord les nouveaux combattants, et seuls ceux qui reviennent vivants sont envoyés ensuite à {link:hammerfall}Trépas-d'Orgrim{/link}. Un {link:ogres}ogre{/link} nommé Kovork rôde sur les collines autour du tertre.]=],
		},
	},
})

Translate("frFR", "dabyrie-s-farmstead", {
	title = "Ferme des Dabyrie",
	sections = {
		{
			title = "Résumé",
			text = [=[La Ferme des Dabyrie s'étend dans le nord des hautes-terres, sur la route qui part vers l'est depuis le {link:refuge-pointe}Refuge de l'Ornière{/link}. C'est la demeure de la famille Dabyrie : Kenata Dabyrie, Fardel et Marcel. Leurs ouvriers travaillent encore ses champs, et une milice qui leur est propre garde les clôtures. Dans un pays de fermes en ruine et de camps de brigands, les Dabyrie sont parmi les rares humains de {link:stromgarde-keep}Stromgarde{/link} qui vivent encore de la terre comme leurs pères. On n'a guère écrit d'autre sur eux.]=],
		},
	},
})

Translate("frFR", "drywhisker-gorge", {
	title = "Gorge des Sèches-moustaches",
	sections = {
		{
			title = "Résumé",
			text = [=[La Gorge des Sèches-moustaches entaille les montagnes à l'extrême nord-est des hautes-terres, au-delà de {link:hammerfall}Trépas-d'Orgrim{/link}. Les {link:drywhisker-kobolds}kobolds Sèches-moustaches{/link} l'ont remplie de leurs tunnels, de leurs arpenteurs et de leurs creuseurs, et un géomancien {link:kobolds}kobold{/link} nommé Flintdagger manie le feu parmi eux. Au fond de la gorge se dresse un amas d'éclats de cristal scintillants. Les kobolds le gardent, et ils portent sur eux des particules d'une étrange puissance. La voix sous les hautes-terres les dit alliés de ses geôliers.]=],
		},
	},
})

Translate("frFR", "arathi-basin", {
	title = "Bassin d'Arathi",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Bassin d'Arathi est une vallée cerclée de montagnes au cœur des hautes-terres, parmi les terres les plus fertiles des {link:eastern-kingdoms}Royaumes de l'est{/link}. Sa ferme, sa mine, sa scierie, sa forge et ses écuries furent bâties pour nourrir un royaume. Aujourd'hui, deux armées se les disputent. La {link:league-of-arathor}Ligue d'Arathor{/link} tient la Salle de Trollbane et compte gagner les richesses du bassin pour {link:stormwind-city}Stormwind{/link} et l'{link:alliance}Alliance{/link}. {link:defilers}Les Profanateurs{/link} réprouvés tiennent L'antre des Profanateurs et comptent couper les humains de leurs alliés nains du sud. Leurs routes partent du {link:refuge-pointe}Refuge de l'Ornière{/link} et de {link:hammerfall}Trépas-d'Orgrim{/link}.]=],
		},
	},
})

Translate("frFR", "captain-nials", {
	title = "Capitaine Nials",
	subtitle = "Commandant du Refuge de l'Ornière",
	found = "Refuge de l'Ornière",
	hint = [=[Parlez au capitaine qui commande le camp du Refuge de l'Ornière.]=],
	allegiance = "Royaume de Stromgarde · Alliance",
	aliases = { "Nials" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le capitaine Nials commande les soldats de {link:stromgarde-keep}Stromgarde{/link} au {link:refuge-pointe}Refuge de l'Ornière{/link}. Elle n'a aucune cité à défendre, seulement l'espoir d'en reconquérir une. Son armée s'amenuise tandis que ses ennemis grandissent, et chaque semaine les ogres, le {link:syndicate}Syndicat{/link} et sa propre milice s'enlisent dans une impasse plus sanglante au milieu des ruines de la capitale.]=],
		},
		{
			title = "Importance",
			text = [=[Nials est la voix d'un royaume qui refuse de mourir. Quand les nains du {link:thandol-span}Viaduc de Thandol{/link} la supplièrent de leur envoyer des soldats, elle refusa, le cœur lourd. L'honneur, dit-elle, retenait son armée dans les hautes-terres jusqu'à ce que la bannière du roi se lève de nouveau sur {link:stromgarde-keep}Stromgarde{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle envoie des combattants contre le {link:syndicate}Syndicat{/link} au {link:northfold-manor}Manoir de Nordclos{/link}, pour garder ouvertes les routes de ravitaillement venant de {link:southshore}Southshore{/link}.
