Translate("frFR", "prince-galen-trollbane", {
	title = "Prince Galen Trollbane",
	subtitle = "Héritier de Stromgarde",
	found = [=[La chapelle du quartier des défenseurs, au Donjon de Stromgarde]=],
	hint = [=[Cherchez le prince qui tient le dernier quartier de Stromgarde.]=],
	allegiance = "Royaume de Stromgarde",
	aliases = { "Galen Trollbane", "Galen" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le prince Galen Trollbane est le fils du roi {link:thoras-trollbane}Thoras{/link} et l'héritier d'un trône déchu. Il tient le dernier coin de {link:stromgarde-keep}Stromgarde{/link} qui soit encore à lui, un quartier de la vieille cité autour de sa chapelle. Derrière cette chapelle repose son père dans son tombeau. Galen garde le tombeau, et il garde l'épée qui s'y trouve.]=],
		},
		{
			title = "Importance",
			text = [=[Galen est le dernier des Trollbane dans les hautes-terres, la lignée d'Ignaeus qui conquit l'épée {link:trol-kalar}Trol'kalar{/link} contre les trolls. Pour les trolls de la {link:horde}Horde{/link}, son sang est celui d'un ennemi ancien. Pour ses soldats, il est tout ce qui reste de leur roi.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il scella le tombeau de son père avec des sceaux et les partagea entre les survivants de {link:stromgarde-keep}Stromgarde{/link}.
• Il brisa le Sceau de {link:thoradin}Thoradin{/link} en morceaux et les confia à ses défenseurs.
• Il donna le Sceau d'{link:arathor}Arathor{/link} au lieutenant {link:lieutenant-valorcall}Valorcall{/link} et garde lui-même le Sceau de Trollbane.
• Il envoie ce qui reste de sa cavalerie chevaucher à travers les hautes-terres.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique de ces jours ne rapporte comment mourut le roi {link:thoras-trollbane}Thoras{/link}, ni comment son fils en vint à régner à sa place.]=],
		},
	},
	chapters = {
		{
			title = "Le sceau partagé",
			hint = [=[Découvrez comment le prince de Stromgarde protège le tombeau de son père.]=],
			text = [=[Le tombeau du roi {link:thoras-trollbane}Thoras{/link} ne peut être ouvert par la force. Galen le lia par des sceaux, et il les dispersa afin qu'aucune défaite ne puisse les faire perdre tous à la fois. L'un d'eux tomba aux mains du {link:syndicate}Syndicat{/link} quand {link:stromgarde-keep}Stromgarde{/link} tomba. Le Sceau de {link:thoradin}Thoradin{/link}, il le brisa en de nombreux morceaux et le partagea entre ses défenseurs, afin qu'il faille le prendre à bien des mains.]=],
		},
		{
			title = "La chapelle",
			hint = [=[Cherchez le prince dans la chapelle du quartier des défenseurs.]=],
			text = [=[Le dernier sceau pendait au côté du prince lui-même, au fond de la chapelle du quartier de la milice. Il était bien gardé, et lui-même n'était pas un piètre combattant. Quand le chasseur {link:darkspear-trolls}Darkspear{/link} {link:zengu}Zengu{/link} tint enfin le sceau entre ses mains, il ne posa qu'une question : la lignée d'Ignaeus Trollbane avait-elle été brisée ?]=],
		},
	},
	mentions = {
		{ text = "Le sceau brisé" },
		{ text = "Le Sceau d'{link:arathor}Arathor{/link}" },
		{ text = "Le Sceau de Trollbane" },
	},
	bonds = {
		{ id = "thoras-trollbane", name = "Thoras Trollbane", note = "son père" },
		{ id = "lieutenant-valorcall", name = "Lieutenant Valorcall", note = "le chef de sa cavalerie" },
		{ id = "zengu", name = "Zengu", note = "cherche son sceau" },
		{ id = "trol-kalar", name = "Trol'kalar", note = "l'épée de sa maison" },
	},
})

