			text = [=[Or'Kalar est un {link:ogres}ogre{/link} qui mène les {link:boulderfist-ogres}Rochepoing{/link} dans les ruines près de la Tour d'{link:arathor}Arathor{/link}. Il sert un ogre plus grand, {link:mug-thol}Mug'thol{/link}, qui le commande de loin. Or'Kalar fut vaincu par {link:drum-fel}Drum Fel{/link} de {link:hammerfall}Trépas-d'Orgrim{/link} il y a des années, et il ne l'a jamais oublié. Les attaques contre Trépas-d'Orgrim sont son œuvre.]=],
		},
		{
			title = "Importance",
			text = [=[La haine d'Or'Kalar est la cause cachée du long siège de {link:hammerfall}Trépas-d'Orgrim{/link}. Il tendit un piège à {link:drum-fel}Drum Fel{/link}, et seule la prévoyance de {link:korin-fel}Korin Fel{/link} empêcha son mari d'y tomber.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il lance les ogres de {link:stromgarde-keep}Stromgarde{/link} contre {link:hammerfall}Trépas-d'Orgrim{/link}.
• Il tendit un piège à {link:drum-fel}Drum Fel{/link} dans les ruines.]=],
		},
	},
	mentions = {
		{ text = "La vraie menace" },
	},
	bonds = {
		{ id = "drum-fel", name = "Drum Fel", note = "l'orc qui l'a vaincu" },
		{ id = "korin-fel", name = "Korin Fel", note = "a caché sa piste à son mari" },
	},
})

