Translate("frFR", "drum-fel", {
	title = "Drum Fel",
	subtitle = "Commandant de Trépas-d'Orgrim",
	found = "Trépas-d'Orgrim",
	hint = "Parlez à l'orc qui mène la défense de Trépas-d'Orgrim.",
	allegiance = "Horde · Trépas-d'Orgrim",
	sections = {
		{
			title = "Résumé",
			text = [=[Drum Fel mène les guerriers de {link:hammerfall}Trépas-d'Orgrim{/link}. Il n'a pas le temps d'affûter sa propre hache, car trolls et ogres frappent ses murs jour après jour. Il a peu de patience pour ceux qui n'ont pas fait leurs preuves, mais il prendra tout combattant assez fort, et il ne manque jamais de combats à leur donner.]=],
		},
		{
			title = "Importance",
			text = [=[Drum Fel est la volonté qui tient {link:hammerfall}Trépas-d'Orgrim{/link}. Il entend montrer aux peuples des hautes-terres que les orcs, eux aussi, ont ici un foyer, et qu'on ne les en chassera pas.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie ses combattants contre les {link:witherbark-trolls}trolls Witherbark{/link} du sud, qui ont tourné le dos aux orcs.
• Il les envoie contre les cogneurs et les mages {link:boulderfist-ogres}Rochepoing{/link} du {link:boulderfist-hall}Hall Rochepoing{/link}.
• Il frappe les seigneurs et les chamans Rochepoing dans les ruines de {link:stromgarde-keep}Stromgarde{/link}.
• Il y a des années, il vainquit l'{link:ogres}ogre{/link} {link:or-kalar}Or'Kalar{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Les registres de {link:hammerfall}Trépas-d'Orgrim{/link} ne disent pas où Drum Fel combattit avant de venir ici, ni quand il rencontra {link:or-kalar}Or'Kalar{/link} pour la première fois.]=],
		},
	},
	chapters = {
		{
			title = "Un foyer dans les hautes-terres",
			hint = [=[Joignez-vous au combat pour défendre Trépas-d'Orgrim contre les trolls.]=],
			text = [=[Les {link:witherbark-trolls}Witherbark{/link} et les {link:boulderfist-ogres}Rochepoing{/link} avaient fait cause commune pour débarrasser les hautes-terres des orcs. Drum Fel connaissait les trolls depuis les jours anciens : ils avaient autrefois combattu aux côtés de la {link:horde}Horde{/link}, puis ils l'avaient quittée. Il n'avait pas l'intention de leur abandonner {link:hammerfall}Trépas-d'Orgrim{/link}. Son premier coup s'abattit sur leurs camps du sud.]=],
		},
		{
			title = "La tête de la bête",
			hint = [=[Portez la guerre aux seigneurs ogres dans les ruines de Stromgarde.]=],
			text = [=[Les chefs des attaques avaient établi leur repaire dans {link:stromgarde-keep}Stromgarde{/link}, que Drum Fel appelait un monument à la faiblesse humaine. Quand ses combattants revinrent des ruines, la pression sur {link:hammerfall}Trépas-d'Orgrim{/link} se relâcha enfin. Il commença à croire que son peuple pourrait prospérer dans les hautes-terres.]=],
		},
	},
	mentions = {
		{ text = "Le marteau pourrait tomber, envoyé par Tallow" },
		{ text = "Aux armes !" },
		{ text = "Aux armes !" },
		{ text = "Aux armes !" },
	},
	bonds = {
		{ id = "korin-fel", name = "Korin Fel", note = "sa femme" },
		{ id = "or-kalar", name = "Or'Kalar", note = "un vieil ennemi" },
		{ id = "gor-mul", name = "Gor'mul", note = "un survivant du camp" },
	},
})

Translate("frFR", "korin-fel", {
	title = "Korin Fel",
	subtitle = "Augure de Trépas-d'Orgrim",
	found = "Trépas-d'Orgrim",
