			title = "La vraie menace",
			hint = [=[Découvrez le secret que garde la femme du commandant de Trépas-d'Orgrim.]=],
			text = [=[Quand {link:or-kalar}Or'Kalar{/link} tomba près de la Tour d'{link:arathor}Arathor{/link}, les attaques contre {link:hammerfall}Trépas-d'Orgrim{/link} cessèrent pour un temps. {link:drum-fel}Drum Fel{/link} ne sut jamais à quel point il était passé près. Korin ne le dit qu'à celui qui avait accompli l'acte.]=],
