	},
	bonds = {
		{ id = "drum-fel", name = "Drum Fel", note = "son mari" },
		{ id = "or-kalar", name = "Or'Kalar", note = "l'ennemi qu'elle a caché" },
	},
})

Translate("frFR", "gor-mul", {
	title = "Gor'mul",
	subtitle = "Survivant du camp",
	found = "Trépas-d'Orgrim",
	hint = [=[Parlez au vieil orc de Trépas-d'Orgrim qui se souvient du camp.]=],
	allegiance = "Horde · Trépas-d'Orgrim",
	sections = {
		{
			title = "Résumé",
			text = [=[Gor'mul fut prisonnier dans le camp qui est aujourd'hui {link:hammerfall}Trépas-d'Orgrim{/link}. Il était là le jour où {link:thrall}Thrall{/link} et Doomhammer vinrent le libérer, et il vit la lance d'un chevalier frapper le chef de guerre dans le dos. Dans le chaos, les autres orcs s'échappèrent. Gor'mul fut laissé en arrière, et il erra seul dans les hautes-terres pendant des années.]=],
		},
		{
			title = "Importance",
			text = [=[Gor'mul porte le deuil de l'ancienne {link:horde}Horde{/link}. Il aurait voulu mourir aux côtés de Doomhammer, et au début aucun récit d'{link:orgrimmar}Orgrimmar{/link} ni du nouveau chef de guerre ne pouvait l'émouvoir.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fut témoin de la mort d'{link:orgrim-doomhammer}Orgrim Doomhammer{/link}.
• Il raconte à chaque nouveau venu comment {link:hammerfall}Trépas-d'Orgrim{/link} fut perdu et reconquis.]=],
		},
	},
	chapters = {
		{
			title = "La ruse du raptor",
			hint = [=[Aidez le chaman de Trépas-d'Orgrim à atteindre le guerrier endeuillé.]=],
			text = [=[Gor'mul jeta la première amulette dans la poussière. Le second présent fut un orbe qui versa en lui l'esprit du raptor, et pour la première fois le vieux guerrier sentit le nouveau pouvoir des chamans. Pour l'instant, dit-il, il écouterait.]=],
		},
	},
	mentions = {
		{ text = "{link:hammerfall}Trépas-d'Orgrim{/link}" },
		{ text = "Éveiller les esprits" },
		{ text = "La ruse du raptor" },
		{ text = "La ruse du raptor" },
	},
	bonds = {
		{ id = "tor-gan", name = "Tor'gan", note = "n'a pas renoncé à lui" },
		{ id = "drum-fel", name = "Drum Fel", note = "son commandant" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "le chef de guerre qu'il a vu tomber" },
	},
})

Translate("frFR", "tor-gan", {
	title = "Tor'gan",
	subtitle = "Chaman de Trépas-d'Orgrim",
	found = "Trépas-d'Orgrim",
	hint = "Parlez au chaman troll de Trépas-d'Orgrim.",
	allegiance = "Horde · Trolls Darkspear",
	sections = {
		{
			title = "Résumé",
			text = [=[Tor'gan est un chaman troll de {link:hammerfall}Trépas-d'Orgrim{/link}. Il est patient là où {link:drum-fel}Drum Fel{/link} est farouche, et il croit que les nouveaux pouvoirs chamaniques de la {link:horde}Horde{/link} peuvent guérir des blessures que les épées ne guérissent pas. Il est aussi sensible à une magie plus sombre. Quand des démons sont invoqués où que ce soit dans les hautes-terres, il le sent brûler dans son sang.]=],
		},
		{
			title = "Importance",
			text = [=[Tor'gan est le guérisseur de l'esprit de {link:hammerfall}Trépas-d'Orgrim{/link}. Il ne voulut pas abandonner {link:gor-mul}Gor'mul{/link}, le guerrier brisé, et il ne voulut pas ignorer la magie démoniaque qui se répand à travers le {link:syndicate}Syndicat{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il découvrit au {link:northfold-manor}Manoir de Nordclos{/link} les traces d'invocation démoniaque, et une amulette de pierre de sang épuisée.
• Il cherche l'orbe de la démoniste qui appelle des démons à {link:stromgarde-keep}Stromgarde{/link}, afin de le détruire.
• Il façonna des amulettes et un orbe à partir des yeux et des cœurs de raptors pour réveiller l'esprit de {link:gor-mul}Gor'mul{/link}.
• Il réunit en un seul les morceaux brisés du Sceau de {link:thoradin}Thoradin{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Magie impie",
			hint = [=[Trouvez la source de la magie démoniaque qui trouble le chaman.]=],
			text = [=[Une puissante démoniste demeurait dans {link:stromgarde-keep}Stromgarde{/link}, et de temps à autre une relique entre ses mains faisait surgir des démons en grand nombre. Quand l'orbe de pierre de sang parvint à Tor'gan, il promit de le détruire. Il lui rappelait, dit-il, le pouvoir que les démons avaient jadis sur les orcs, avant que Hellscream ne brise leur malédiction.]=],
		},
		{
			title = "Un guerrier réveillé",
			hint = "Aidez le chaman à rendre à Gor'mul son esprit.",
			text = [=[La première amulette de Tor'gan échoua. Il ne se découragea pas. Il réunit des cœurs de raptors et lia leur esprit dans un orbe, et {link:gor-mul}Gor'mul{/link} sentit enfin ce dont le chaman était capable. Tor'gan attendit que l'enchantement se dissipe, puis il alla lui parler.]=],
		},
		{
			title = "Le sceau restauré",
			hint = "Apportez le sceau brisé de Stromgarde au chaman troll.",
			text = [=[Les fragments du Sceau de {link:thoradin}Thoradin{/link} parvinrent à Tor'gan, pris sur les corps des défenseurs de {link:stromgarde-keep}Stromgarde{/link}. La magie qui l'avait tenu était encore là. Dans un éclair de lumière, il le rendit entier et le renvoya à {link:zengu}Zengu{/link}.]=],
		},
	},
	mentions = {
		{ text = "Magie impie" },
		{ text = "Magie impie" },
		{ text = "Éveiller les esprits" },
		{ text = "La ruse du raptor" },
		{ text = "Le sceau brisé" },
		{ text = "Le Sceau de {link:thoradin}Thoradin{/link}" },
	},
	bonds = {
		{ id = "gor-mul", name = "Gor'mul", note = "le guerrier qu'il a guéri" },
		{ id = "zengu", name = "Zengu", note = "son allié dans la quête de l'épée" },
		{ id = "marez-cowl", name = "Marez Cowl", note = "la démoniste qu'il traque" },
	},
})

Translate("frFR", "zengu", {
	title = "Zengu",
	subtitle = "Chasseur des Darkspear",
	found = "Trépas-d'Orgrim",
	hint = [=[Parlez au chasseur Darkspear venu à Trépas-d'Orgrim en mission.]=],
	allegiance = "Trolls Darkspear · Horde",
	sections = {
		{
			title = "Résumé",
			text = [=[Zengu est un chasseur aguerri des {link:darkspear-trolls}Darkspear{/link}. {link:vol-jin}Vol'jin{/link} l'a envoyé à {link:hammerfall}Trépas-d'Orgrim{/link} avec une seule tâche : prendre l'épée {link:trol-kalar}Trol'kalar{/link} dans le tombeau des Trollbane. Les Darkspear comptent la porter dans leur guerre contre les trolls de {link:zul-gurub}Zul’Gurub{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Dans la traque de Zengu, la plus ancienne guerre des hautes-terres boucle la boucle. La lame que les seigneurs de {link:stromgarde-keep}Strom{/link} tournèrent jadis contre les trolls est recherchée par des trolls, pour être tournée contre d'autres trolls.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il suit la piste des quatre sceaux qui ferment le tombeau du roi {link:thoras-trollbane}Thoras{/link}.
• Il prend le premier sceau au {link:syndicate}Syndicat{/link}, à {link:stromgarde-keep}Stromgarde{/link}.
• Il traque le chef de cavalerie {link:lieutenant-valorcall}Valorcall{/link} pour le Sceau d'{link:arathor}Arathor{/link}.
• Il cherche le dernier sceau auprès du prince {link:prince-galen-trollbane}Galen{/link} lui-même.]=],
		},
	},
	chapters = {
		{
			title = "Le Sceau de Strom",
			hint = [=[Cherchez le premier des sceaux qui gardent le tombeau des Trollbane.]=],
			text = [=[Zengu connaît la vieille histoire. Quand les trolls combattaient l'empire d'{link:arathor}Arathor{/link}, leur plus grand ennemi était Lord Ignaeus de {link:stromgarde-keep}Strom{/link}, appelé Trollbane, qui partait en guerre avec la lame {link:trol-kalar}Trol'kalar{/link}, la tueuse de trolls. Désormais, les fils de Trollbane étaient faibles, et leur place forte était en ruine. Le {link:syndicate}Syndicat{/link} tenait le premier sceau. Zengu commença par là.]=],
		},
		{
			title = "L'épée libérée",
			hint = "Ouvrez le tombeau des Trollbane.",
			text = [=[Les quatre sceaux s'unirent en un seul, le Sceau d'Ignaeus. Ses lignes correspondaient aux gravures du tombeau dans le Sanctuaire, et les mains de pierre rendirent leur épée. Pendant des générations, dit Zengu, {link:stromgarde-keep}Strom{/link} et {link:arathor}Arathor{/link} avaient ravagé les trolls. Désormais, leur plus grande arme appartenait aux {link:darkspear-trolls}Darkspear{/link}, et il veillerait à ce qu'elle soit portée à {link:nimboya}Nimboya{/link}, au {link:grom-gol-base-camp}Campement Grom'gol{/link}.]=],
		},
	},
	mentions = {
		{ text = "Trollbane, envoyé par {link:nimboya}Nimboya{/link}" },
		{ text = "Le Sceau de {link:stromgarde-keep}Strom{/link}" },
		{ text = "Le sceau brisé" },
		{ text = "Le Sceau d'{link:arathor}Arathor{/link}" },
		{ text = "Le Sceau de Trollbane" },
		{ text = "{link:trol-kalar}Trol'kalar{/link}" },
		{ text = "{link:trol-kalar}Trol'kalar{/link}" },
	},
	bonds = {
		{ id = "vol-jin", name = "Vol'jin", note = "l'a envoyé" },
		{ id = "tor-gan", name = "Tor'gan", note = "a restauré le sceau brisé" },
		{ id = "prince-galen-trollbane", name = "Prince Galen Trollbane", note = "garde le dernier sceau" },
		{ id = "trol-kalar", name = "Trol'kalar", note = "l'épée qu'il cherche" },
	},
})

Translate("frFR", "zaruk", {
