		{ id = "theldurin-the-lost", name = "Theldurin the Lost", note = "le traître à son ordre" },
	},
})

Translate("frFR", "deathmaster-dwire", {
	title = "Maître de la mort Dwire",
	subtitle = "Commandant des Profanateurs",
	found = "Trépas-d'Orgrim",
	hint = [=[Parlez au Réprouvé qui commande les Profanateurs à Trépas-d'Orgrim.]=],
	allegiance = "Profanateurs · Réprouvés",
	aliases = { "Dwire" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le maître de la mort Dwire mène les {link:defilers}Profanateurs{/link} depuis {link:hammerfall}Trépas-d'Orgrim{/link}. Il voit dans le petit camp du {link:refuge-pointe}Refuge de l'Ornière{/link} le germe d'un danger plus grand, et il entend l'écraser avant qu'il ne grandisse. L'{link:alliance}Alliance{/link} ne doit plus jamais faire d'{link:arathi-highlands}Arathi{/link} un foyer pour les humains.]=],
		},
		{
			title = "Importance",
			text = [=[Dwire est le fer de lance réprouvé de la guerre pour les hautes-terres. Ses {link:defilers}Profanateurs{/link} ne combattent pas pour les orcs de {link:hammerfall}Trépas-d'Orgrim{/link}, mais pour {link:undercity}Undercity{/link} et sa reine.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie ses soldats dans le {link:arathi-basin}Bassin d'Arathi{/link} pour abattre les bannières de la Ligue sur la mine, la scierie, la forge et les écuries.
