Translate("frFR", "myzrael", {
	title = "Myzrael",
	subtitle = "La princesse de la terre",
	found = [=[Sous les Hautes-terres d'Arathi ; elle parle à travers les éclats de Myzrael]=],
	hint = [=[Écoutez la voix qui supplie à travers un cristal dans les montagnes du nord.]=],
	allegiance = "Elle-même · servie par le Marteau du crépuscule",
	sections = {
		{
			title = "Résumé",
			text = [=[Myzrael est un être des profondeurs de la terre qui gît enchaîné sous les {link:arathi-highlands}Hautes-terres d'Arathi{/link}. Elle se dit princesse de la terre. Les géants l'y ont enchaînée, et quatre Pierres de lien la retiennent captive. Ce n'est qu'à travers des éclats de cristal qu'elle peut parler au monde d'en haut, et elle parle avec douceur, suppliant qu'on la sauve.]=],
		},
		{
			title = "Importance",
			text = [=[Myzrael est le secret des hautes-terres. Le {link:twilight-s-hammer}Marteau du crépuscule{/link} l'appelle la Dame et œuvre à son retour. Celui qui a fui leur ordre avec son parchemin croit que les géants l'ont enchaînée pour une raison, et qu'il ne faut jamais la laisser devenir puissante.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle appelle les voyageurs en visions à travers un éclat de son cristal.
• Elle les envoie éveiller les éclats que détiennent les {link:drywhisker-kobolds}kobolds Sèches-moustaches{/link}.
• Elle demande les trois clés des Pierres de lien, et le Bâton de l'Ordre du guetteur de pierre {link:fozruk}Fozruk{/link}.
• Elle nomme des alliés à elle à {link:ironforge}Ironforge{/link} et à {link:hammerfall}Trépas-d'Orgrim{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique d'{link:azeroth}Azeroth{/link} ne parle de Myzrael. Ce qu'elle est, d'où elle vient et pourquoi les géants l'ont enchaînée ne sont connus que par ses propres paroles et par celles de {link:theldurin-the-lost}Theldurin{/link} the Lost.]=],
		},
	},
	chapters = {
		{
			title = "La voix dans le cristal",
			hint = [=[Répondez à la supplique qui vient d'un cristal dans les montagnes du nord.]=],
			text = [=[Un éclat palpita dans la main, et vint la vision d'un cristal dans les montagnes du nord. Là, la voix donna son nom : Myzrael, piégée tout au fond par des géants. Elle demanda de l'aide, et elle la demanda avec douceur.]=],
		},
		{
			title = "Libre",
			hint = "Ouvrez la clé de voûte du Cercle de lien intérieur.",
			text = [=[Quand le Bâton de l'Ordre tourna dans la clé de voûte, le sol trembla. Myzrael s'écria qu'elle était libre. Elle ne comptait pas encore affronter ses geôliers. Elle se cacherait, deviendrait forte, et un jour ferait payer aux géants leur garde. Quand elle serait prête, il faudrait l'invoquer.]=],
		},
		{
			title = "Les entraves",
			hint = "Découvrez ce que sait le gardien fou du parchemin.",
			text = [=[{link:theldurin-the-lost}Theldurin{/link} the Lost avait volé le parchemin de Myzrael, et il l'avait lu. Il fallait l'invoquer et la vaincre avant qu'elle n'ait réuni sa puissance, dit-il, et la lier de nouveau avec ses propres entraves surnaturelles. Quand les entraves se refermèrent autour des éclats, un cri monta de très loin en dessous, puis un rugissement. Les éclats avaient autrefois semblé chauds au toucher. Désormais, ils ne faisaient que menacer.]=],
		},
	},
	mentions = {
		{ text = "Le cristal dans les montagnes" },
		{ text = "La princesse prisonnière" },
		{ text = "Les Pierres de lien" },
		{ text = "Briser la clé de voûte" },
		{ text = "Les alliés de Myzrael" },
		{ text = "Les alliés de Myzrael" },
		{ text = "{link:theldurin-the-lost}Theldurin{/link} the Lost" },
		{ text = "Invoquer la princesse" },
	},
	bonds = {
		{ id = "zaruk", name = "Zaruk", note = "la sert à Trépas-d'Orgrim" },
		{ id = "gerrig-bonegrip", name = "Gerrig Bonegrip", note = "la sert à Ironforge" },
		{ id = "fozruk", name = "Fozruk", note = "l'un de ses geôliers" },
		{ id = "theldurin-the-lost", name = "Theldurin the Lost", note = "a fui avec son parchemin" },
	},
})

Translate("frFR", "thoradin", {
	title = "Thoradin",
	subtitle = "Premier roi d'Arathor",
	sections = {
		{
			title = "Résumé",
			text = [=[Thoradin fut le seigneur de guerre de la tribu {link:arathi-highlands}Arathi{/link} qui fit de l'humanité une nation. En un âge où les tribus humaines du nord se combattaient entre elles tandis que les trolls les chassaient toutes, il les unit sous une seule bannière. Il nomma le nouveau royaume {link:arathor}Arathor{/link} et éleva sa capitale, {link:stromgarde-keep}Strom{/link}, dans les hautes-terres qui portent le nom de sa tribu. Tous les royaumes humains d'aujourd'hui descendent de son œuvre.]=],
		},
		{
			title = "Importance",
			text = [=[Avant Thoradin, il y avait des tribus. Après lui, il y eut un peuple. Son alliance avec les elfes gagna les {link:troll-wars}guerres des Trolls{/link} et apporta à l'humanité la connaissance de la magie, et sa lignée fut honorée par les elfes de {link:quel-thalas}Quel'Thalas{/link} pendant des milliers d'années. Le grand mur entre les hautes-terres et {link:hillsbrad-foothills}Hillsbrad{/link} porte encore son nom.]=],
		},
		{
			title = "L'union des tribus",
			text = [=[Les {link:arathi-highlands}Arathi{/link} avaient combattu les Amani plus longtemps que toute autre tribu, et Thoradin avait appris la guerre sur la frontière des trolls. Il vit ce que les autres chefs refusaient de voir : que les trolls détruiraient les tribus une à une. Il les rassembla par tous les moyens dont il disposait. Il en gagna certaines par des mariages, d'autres par des promesses de terres et de richesses, et il en vainquit d'autres au combat. Ceux qu'il avait vaincus, il ne les humilia pas. Il fit de leurs chefs ses généraux, et ils devinrent ainsi ses hommes les plus loyaux.]=],
		},
		{
			title = "Strom",
			text = [=[Thoradin établit sa capitale sur les plaines sèches des hautes-terres, loin des forêts denses où les trolls tendaient leurs embuscades. La forteresse de {link:stromgarde-keep}Strom{/link} devint un lieu de refuge, et des humains y vinrent de tout le continent. C'est ici aussi que l'humanité apprit pour la première fois les arts arcaniques.]=],
		},
		{
			title = "Les guerres des Trolls",
			text = [=[Quand les Amani fondirent sur {link:quel-thalas}Quel'Thalas{/link}, les elfes envoyèrent des émissaires à {link:stromgarde-keep}Strom{/link}. Ils promirent d'enseigner les voies de la magie à cent humains en échange des épées d'{link:arathor}Arathor{/link}. Thoradin accepta. Son armée frappa les trolls au sud des terres elfiques et les attira dans les contreforts des {link:alterac-mountains}Montagnes d'Alterac{/link}, où les elfes et les nouveaux mages humains fondirent sur eux par l'autre côté. Les Amani furent brisés. En remerciement, les elfes jurèrent un serment d'amitié à la lignée de Thoradin.]=],
		},
		{
			title = "L'héritage",
			text = [=[Thoradin souhaitait que {link:stromgarde-keep}Strom{/link} demeure le cœur de son royaume, et il craignait un empire trop étendu. Après lui, son peuple partit malgré tout et fonda {link:dalaran}Dalaran{/link}, Gilnéas, {link:kul-tiras}Kul Tiras{/link}, {link:alterac-mountains}Alterac{/link} et Lordaeron. Strom déclina. Enfin, le dernier de sa lignée la quitta et fit voile vers le sud pour fonder un nouveau royaume. Bien des siècles plus tard, {link:anduin-lothar}Anduin Lothar{/link}, le dernier de cette lignée, mena l'{link:alliance}Alliance{/link} de {link:lordaeron}Lordaeron{/link} pendant la {link:second-war}Deuxième Guerre{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Les histoires disent peu de chose de la famille de Thoradin, de ses dernières années ou de sa mort. Cette entrée ne cherche pas à les deviner.]=],
		},
	},
	chapters = {
		{
			title = "Le Sceau de Thoradin",
			hint = "Suivez le sceau brisé qui porte le nom du premier roi.",
			text = [=[Parmi les sceaux qui gardent le tombeau des Trollbane se trouve un sceau qui porte le nom de Thoradin. Le prince {link:prince-galen-trollbane}Galen{/link} le brisa et en dispersa les morceaux parmi ses derniers défenseurs. Les morceaux furent pris sur leurs corps, et un chaman troll de la {link:horde}Horde{/link} les réunit de nouveau. Le nom du premier roi était devenu une clé entre les mains des trolls que son peuple avait jadis vaincus.]=],
		},
	},
	mentions = {
		{ text = "Le sceau brisé" },
		{ text = "Le Sceau de Thoradin" },
	},
	bonds = {
		{ id = "arathor", name = "Arathor", note = "la nation qu'il fonda" },
		{ id = "anduin-lothar", name = "Anduin Lothar", note = "le dernier de sa lignée" },
		{ id = "thoradin-s-wall", name = "Mur de Thoradin", note = "porte son nom" },
		{ id = "stromgarde-keep", name = "Donjon de Stromgarde", note = "autrefois sa capitale, Strom" },
	},
})

Translate("frFR", "thoras-trollbane", {
	title = "Thoras Trollbane",
	subtitle = "Feu roi de Stromgarde",
	allegiance = "Royaume de Stromgarde · Maison Trollbane",
	aliases = { "Thoras", "Roi Thoras" },
	sections = {
		{
			title = "Résumé",
			text = [=[Thoras Trollbane était le roi de {link:stromgarde-keep}Stromgarde{/link}, héritier de l'antique maison qui régnait sur la cité depuis que la lignée royale d'{link:arathor}Arathor{/link} l'avait quittée. Il était un roi guerrier dans un pays de rudes soldats. Il est mort aujourd'hui, et son royaume est mort avec lui. Il repose dans un tombeau scellé dans le Sanctuaire, derrière la chapelle de Stromgarde, avec l'épée de sa maison à ses côtés.]=],
		},
		{
			title = "Importance",
			text = [=[Thoras fut l'un des souverains qui levèrent l'{link:alliance}Alliance{/link} de {link:lordaeron}Lordaeron{/link} contre la {link:horde}Horde{/link}. Sa maison descend d'Ignaeus, le général des guerres des {link:trolls}Trolls{/link} dont la lame {link:trol-kalar}Trol'kalar{/link} valut son nom à la famille. Pour les trolls d'{link:azeroth}Azeroth{/link}, le nom de Trollbane est encore une malédiction.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il mena {link:stromgarde-keep}Stromgarde{/link} dans l'{link:alliance}Alliance de Lordaeron{/link} pendant la {link:second-war}Deuxième Guerre{/link}.
• Après la guerre, quand l'Alliance se querella au sujet des camps d'internement et de leur coût, il en retira Stromgarde.
• Il fut inhumé avec {link:trol-kalar}Trol'kalar{/link}, l'épée d'Ignaeus.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique de ces jours ne rapporte comment mourut Thoras Trollbane. Son peuple dit seulement qu'il n'est plus.]=],
		},
	},
	chapters = {
		{
			title = "Le tombeau du Sanctuaire",
			hint = "Tenez-vous devant le tombeau du dernier roi de Stromgarde.",
			text = [=[Le tombeau du roi Thoras se trouve derrière la chapelle du quartier des défenseurs, veillé par des gardiens de la maison. Sa face est gravée de lignes qu'aucune main ne peut ouvrir sans les sceaux que son fils dispersa. Dans l'étreinte de mains de pierre posées sur le tombeau repose {link:trol-kalar}Trol'kalar{/link}.]=],
		},
	},
	mentions = {
		{ text = "Trollbane, la nouvelle de sa mort" },
		{ text = "{link:trol-kalar}Trol'kalar{/link}" },
	},
	bonds = {
		{ id = "prince-galen-trollbane", name = "Prince Galen Trollbane", note = "son fils" },
		{ id = "terenas-menethil", name = "Terenas Menethil", note = "son allié dans l'Alliance" },
		{ id = "trol-kalar", name = "Trol'kalar", note = "l'épée de sa maison" },
	},
})

Translate("frFR", "trol-kalar", {
	title = "Trol'kalar",
	sections = {
		{
			title = "Résumé",
			text = [=[Trol'kalar est l'antique épée de la maison Trollbane. Son nom signifie tueuse de trolls dans la langue même des trolls. Elle fut portée pendant les guerres d'{link:arathor}Arathor{/link} par Lord Ignaeus de {link:stromgarde-keep}Strom{/link}, l'ennemi le plus redouté que les trolls aient jamais affronté, et elle donna son nom à sa maison.]=],
		},
		{
			title = "Le tombeau",
			text = [=[Quand le roi {link:thoras-trollbane}Thoras{/link} mourut, Trol'kalar fut déposée dans son tombeau du Sanctuaire, derrière la chapelle de {link:stromgarde-keep}Stromgarde{/link}, tenue dans l'étreinte de mains de pierre. Le tombeau fut scellé par des protections qui ne répondent qu'à un sceau. Le prince {link:prince-galen-trollbane}Galen{/link} divisa ce sceau en quatre : le Sceau de Strom, le Sceau de {link:thoradin}Thoradin{/link}, le Sceau d'{link:arathor}Arathor{/link} et le Sceau de Trollbane. L'un tomba aux mains du {link:syndicate}Syndicat{/link} avec la cité. Il donna les autres à ses soldats, au chef de sa cavalerie et à lui-même. Réunis, les quatre n'en forment plus qu'un, le Sceau d'Ignaeus.]=],
		},
		{
			title = "Au temps présent",
			text = [=[{link:vol-jin}Vol'jin{/link} des {link:darkspear-trolls}Darkspear{/link} veut l'épée. Il a envoyé le chasseur {link:zengu}Zengu{/link} à {link:hammerfall}Trépas-d'Orgrim{/link} pour la prendre, afin que la tueuse de trolls de {link:stromgarde-keep}Strom{/link} soit tournée contre les trolls Gurubashi de {link:zul-gurub}Zul’Gurub{/link}.]=],
		},
	},
})

Translate("frFR", "witherbark-trolls", {
	title = "Trolls Witherbark",
	aliases = { "Witherbark", "trolls Witherbark", "tribu Witherbark" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Witherbark sont une tribu de {link:trolls}trolls{/link} des forêts qui vivent au sud-est des {link:arathi-highlands}Hautes-terres d'Arathi{/link}. Leur village se dresse parmi les collines, avec derrière lui des cavernes où se réunissent leurs chefs de bande. Les trolls combattent les humains de {link:stromgarde-keep}Strom{/link} depuis l'époque de {link:thoradin}Thoradin{/link}, et les Witherbark tiennent encore cette guerre à cœur.]=],
		},
		{
			title = "Leurs coutumes",
			text = [=[La tribu compte des lanceurs de haches, des chasseurs de têtes, des berserkers et des sorciers-docteurs qui portent des sacoches de remèdes et des amulettes de pierre de sang. Ses chasseurs des ombres reçoivent un couteau particulier quand ils achèvent leurs rites de passage. Deux chefs de bande, Zalas Witherbark et Nimar the Slayer, les mènent à la guerre.]=],
		},
		{
			title = "Au temps présent",
			text = [=[Les Witherbark combattaient autrefois aux côtés des orcs, puis ils les quittèrent. Ils se sont maintenant joints aux {link:boulderfist-ogres}ogres Rochepoing{/link} pour chasser la {link:horde}Horde{/link} de {link:hammerfall}Trépas-d'Orgrim{/link}. Leurs combattants partagent le tertre {link:ogres}ogre{/link} de {link:boulder-gor}Boulder'gor{/link}, et des berserkers de la tribu se tiennent aux côtés des ogres dans les ruines de {link:stromgarde-keep}Stromgarde{/link}. {link:drum-fel}Drum Fel{/link} de Trépas-d'Orgrim en a fait la première cible de sa guerre.]=],
		},
	},
})

Translate("frFR", "boulderfist-ogres", {
	title = "Ogres Rochepoing",
	aliases = { "Rochepoing", "ogres Rochepoing", "clan Rochepoing" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Rochepoing sont le plus grand clan d'{link:ogres}ogres{/link} des {link:arathi-highlands}Hautes-terres d'Arathi{/link}. Ils tiennent le tertre de {link:boulder-gor}Boulder'gor{/link}, les grottes du {link:boulderfist-hall}Hall Rochepoing{/link} et une grande partie de la cité en ruine de {link:stromgarde-keep}Stromgarde{/link}. Aucune chronique ne dit quand ils vinrent dans les hautes-terres.]=],
		},
		{
			title = "Leurs coutumes",
			text = [=[Ce sont des brutes, des exécuteurs, des cogneurs et des seigneurs, avec des mages et des chamans qui ont appris à se servir des trésors qu'ils pillent. Leurs chamans prisent les agates azur prises dans la Tour d'{link:arathor}Arathor{/link}. Au {link:boulderfist-hall}Hall Rochepoing{/link}, l'{link:ogres}ogre{/link} mage {link:kor-gresh-coldrage}Kor'gresh Coldrage{/link} lance de la glace avec une baguette volée. À {link:stromgarde-keep}Stromgarde{/link}, l'ogre {link:or-kalar}Or'Kalar{/link} les commande au nom de {link:mug-thol}Mug'thol{/link}, un seigneur de guerre qui n'est pas des hautes-terres.]=],
		},
		{
			title = "Au temps présent",
			text = [=[Les Rochepoing disputent les ruines de la cité aux soldats de {link:stromgarde-keep}Stromgarde{/link} et au {link:syndicate}Syndicat{/link}, et ils se sont joints aux {link:witherbark-trolls}trolls Witherbark{/link} contre {link:hammerfall}Trépas-d'Orgrim{/link}. Kovork, Molok the Crusher, {link:ruul-eagletalon}Ruul{/link} Onestone et Foulbelly sont redoutés parmi leurs chefs.]=],
		},
	},
})

Translate("frFR", "drywhisker-kobolds", {
	title = "Kobolds Sèches-moustaches",
	aliases = { "Sèches-moustaches", "kobolds Sèches-moustaches" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Sèches-moustaches sont une tribu de {link:kobolds}kobolds{/link} qui creusent dans la {link:drywhisker-gorge}Gorge des Sèches-moustaches{/link}, à l'extrême nord-est des hautes-terres. Ce sont des arpenteurs et des creuseurs, et parmi eux travaille un géomancien nommé Flintdagger qui commande au feu.]=],
		},
		{
			title = "Les éclats",
			text = [=[Les Sèches-moustaches ne sont pas que des mineurs. Au fond de leur gorge, ils gardent un amas d'éclats de cristal irisés, et ils portent sur eux des particules d'une étrange puissance. L'être qui gît enchaîné sous les hautes-terres les dit alliés des géants qui la retiennent. Trois d'entre eux marchent aux côtés du guetteur de pierre {link:fozruk}Fozruk{/link} lui-même. Nul ne sait ce que les géants ont donné aux kobolds pour leurs services, ni si les kobolds comprennent seulement qui ils servent.]=],
		},
	},
})

Translate("frFR", "league-of-arathor", {
	title = "Ligue d'Arathor",
	sections = {
		{
			title = "Résumé",
			text = [=[La Ligue d'Arathor est la force combattante de ce qui reste du royaume de {link:stromgarde-keep}Stromgarde{/link}. Ses soldats sont les héritiers d'un fier royaume dont la capitale est aujourd'hui tenue par des ogres et des brigands. Ils ont juré de reconquérir les hautes-terres pour le peuple de Stromgarde et pour l'{link:alliance}Alliance{/link}.]=],
		},
		{
			title = "Leur cause",
			text = [=[La Ligue a établi son camp au {link:refuge-pointe}Refuge de l'Ornière{/link} sous les ordres du grand maréchal {link:field-marshal-oslight}Oslight{/link}. Sa première bataille est pour le {link:arathi-basin}Bassin d'Arathi{/link}, une vallée fertile de fermes, de mines, de forges et de forêts. La Ligue entend réclamer les richesses du bassin pour ses alliés de {link:stormwind-city}Stormwind{/link}, et à travers Stormwind pour toute l'{link:alliance}Alliance{/link}. Ses soldats tiennent la Salle de Trollbane, au bord de la vallée, qui porte le nom de la maison royale de {link:stromgarde-keep}Stromgarde{/link}.]=],
		},
		{
			title = "Au temps présent",
			text = [=[La Ligue affronte les {link:defilers}Profanateurs réprouvés{/link} dans le bassin. Son officier de ravitaillement, Samuel Hawke, envoie des vivres à ceux qui combattent, et ses sergents pressent chaque soldat de frapper avant que l'ennemi ne le puisse.]=],
		},
	},
})

Translate("frFR", "defilers", {
	title = "Profanateurs",
	aliases = { "Les Profanateurs", "Profanateurs réprouvés" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Profanateurs sont des troupes d'élite des {link:forsaken}Réprouvés{/link}, envoyées dans les {link:arathi-highlands}Hautes-terres d'Arathi{/link} sous l'œil vigilant de {link:varimathras}Varimathras{/link}. Ils disputent le {link:arathi-basin}Bassin d'Arathi{/link} à la {link:league-of-arathor}Ligue d'Arathor{/link}. Leur but n'est pas la guerre des orcs, mais celle de leur propre reine : couper les humains du nord de leurs alliés nains du sud, et s'emparer des richesses du bassin pour {link:undercity}Undercity{/link}.]=],
		},
		{
			title = "Leur camp",
			text = [=[Les Profanateurs ont leur quartier général à {link:hammerfall}Trépas-d'Orgrim{/link}, aux côtés des orcs et des trolls de l'avant-poste, sous les ordres du maître de la mort {link:deathmaster-dwire}Dwire{/link}. Dans le bassin, ils tiennent L'antre des Profanateurs. Leur officier de ravitaillement, Rutherford Twing, envoie des vivres à ceux qui combattent pour eux, et le traqueur noir Mortis sert aux côtés de Dwire.]=],
		},
		{
			title = "Au temps présent",
			text = [=[{link:deathmaster-dwire}Dwire{/link} croit que même le petit camp du {link:refuge-pointe}Refuge de l'Ornière{/link} pourrait un jour menacer la {link:horde}Horde{/link}. Les Profanateurs entendent faire en sorte qu'{link:arathi-highlands}Arathi{/link} ne redevienne jamais un foyer pour les humains.]=],
		},
	},
})
